create table users (id bigint generated by default as identity primary key, name varchar(100) not null, email varchar(254) not null unique, password_hash varchar(255) not null, role varchar(255) not null, created_at timestamp(6) with time zone not null);
create table products (id bigint generated by default as identity primary key, sku varchar(50) not null unique, title varchar(150) not null, description varchar(3000) not null, category varchar(50) not null, art varchar(255) not null, price_minor_units bigint not null check(price_minor_units>=100), stock_quantity integer not null check(stock_quantity>=0), active boolean not null);
create table cart_items (id bigint generated by default as identity primary key, user_id bigint not null references users(id), product_id bigint not null references products(id), quantity integer not null check(quantity between 1 and 99), unique(user_id,product_id));
create table orders (id bigint generated by default as identity primary key, user_id bigint not null references users(id), status varchar(255) not null, total_minor_units bigint not null check(total_minor_units>0), currency varchar(255) not null, gateway_order_id varchar(255) unique, request_token varchar(255) not null unique, address varchar(1000) not null, created_at timestamp(6) with time zone not null);
create table order_items (id bigint generated by default as identity primary key, order_id bigint not null references orders(id), product_id bigint not null references products(id), product_name_snapshot varchar(255) not null, unit_price_minor_units bigint not null, quantity integer not null check(quantity>0));
create table payments (id bigint generated by default as identity primary key, order_id bigint not null references orders(id), gateway_payment_id varchar(255) not null unique, gateway_order_id varchar(255) not null, amount_minor_units bigint not null, currency varchar(255) not null, status varchar(255) not null, created_at timestamp(6) with time zone not null);
create table refunds (id bigint generated by default as identity primary key, payment_id bigint not null references payments(id), gateway_refund_id varchar(255) unique, request_token varchar(255) not null unique, amount_minor_units bigint not null check(amount_minor_units>=100), status varchar(255) not null, created_at timestamp(6) with time zone not null);
create table webhook_events (id bigint generated by default as identity primary key, gateway_event_id varchar(255) not null unique, event_type varchar(255) not null, processed_at timestamp(6) with time zone not null, status varchar(255) not null);
create table audit_entries (id bigint generated by default as identity primary key, order_id bigint not null references orders(id), kind varchar(255) not null, detail varchar(500) not null, created_at timestamp(6) with time zone not null);
create index idx_order_user on orders(user_id);
create index idx_payment_order on payments(order_id);
create index idx_refund_payment on refunds(payment_id);
create index idx_audit_order on audit_entries(order_id);
